#include <string.h>

// (copy struct, hash, ht_create, ht_put, ht_get từ bài 1)
// TODO: bool ht_remove(HashTable *ht, const char *key)

int main() {
    HashTable *ht = ht_create(8);  // capacity nhỏ để dễ va chạm

    // Thêm nhiều key để tạo va chạm
    ht_put(ht, "A", 1);
    ht_put(ht, "B", 2);
    ht_put(ht, "C", 3);
    ht_put(ht, "D", 4);

    // Test xóa key đầu bucket
    ht_remove(ht, "A");
    int v; ht_get(ht, "A", &v) ? printf("A: %d\n", v) : printf("A: DELETED\n");

    // Test xóa key giữa
    ht_remove(ht, "C");
    ht_get(ht, "C", &v) ? printf("C: %d\n", v) : printf("C: DELETED\n");

    // Test xóa key không có
    bool ok = ht_remove(ht, "ZZZ");
    printf("Remove ZZZ: %s\n", ok ? "OK" : "NOT FOUND");

    ht_free(ht);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// (copy toàn bộ code từ bài 1,2)
// TODO: void ht_rehash(HashTable *ht)
// Trong ht_put: sau khi ht->size++, nếu (double)ht->size/ht->capacity > 0.75 thì ht_rehash(ht)

int main() {
    HashTable *ht = ht_create(8);  // nhỏ để trigger rehash sớm

    printf("Initial capacity: %zu\n", ht->capacity);

    for (int i = 0; i < 20; i++) {
        char key[16];
        sprintf(key, "key%d", i);
        ht_put(ht, key, i * 10);
    }

    printf("Final capacity: %zu\n", ht->capacity);
    printf("Size: %zu\n", ht->size);
    printf("Load factor: %.2f\n", (double)ht->size / ht->capacity);

    // Verify data intact after rehash
    int val;
    for (int i = 0; i < 20; i++) {
        char key[16];
        sprintf(key, "key%d", i);
        if (!ht_get(ht, key, &val) || val != i * 10) {
            printf("ERROR at %s\n", key);
            break;
        }
    }
    printf("All data verified!\n");

    ht_free(ht);
    return 0;
}
